// Enforce one-time initialization using a global attribute.
int already = FUZZ_GET_ATTR_INT_GLOBAL("sxt_initialized");
if (already) { FUZZ_BAIL(); }

// Build a valid config in-place. Backend is chosen from {CPU,GPU} modeled as {0,1}.
struct sxt_config cfg;
cfg.backend = (int)(*FUZZ_PARAM(unsigned int) % 2); // 0 or 1
cfg.num_precomputed_generators = (uint64_t)(*FUZZ_PARAM(unsigned int) % 1024);

int rc = sxt_init(&cfg);
if (rc != 0) { FUZZ_BAIL(); }

// Mark initialized and record backend for downstream checks.
FUZZ_SET_ATTR_INT_GLOBAL("sxt_initialized", 1);
FUZZ_SET_ATTR_INT_GLOBAL("sxt_backend", cfg.backend);

// Requires library initialization.
if (!FUZZ_GET_ATTR_INT_GLOBAL("sxt_initialized")) { FUZZ_BAIL(); }

// Choose a small number of sequences to keep allocations modest.
uint32_t num_sequences = (uint32_t)(*FUZZ_PARAM(unsigned int) % 4);

// Prepare descriptors respecting constraints.
std::vector<struct sxt_sequence_descriptor> descs(num_sequences);
std::vector<std::string> backing(num_sequences); // owns data buffers
for (uint32_t i = 0; i < num_sequences; ++i) {
    unsigned k = (unsigned)(*FUZZ_PARAM(unsigned int) % 6); // 0..5 -> 1..32
    uint8_t element_nbytes = (uint8_t)(1u << k);
    int is_signed = (int)(*FUZZ_PARAM(unsigned int) & 1u);
    if (is_signed && element_nbytes > 16) element_nbytes = 16; // signed requires <=16
    uint64_t n = (uint64_t)(*FUZZ_PARAM(unsigned int) % 16); // cap length

    descs[i].element_nbytes = element_nbytes;
    descs[i].n = n;
    descs[i].is_signed = is_signed;

    if (n > 0) {
        size_t need = (size_t)(n * element_nbytes);
        std::string s = FUZZ_PARAM_STR();
        if (s.size() < need) s.resize(need, '\0');
        backing[i] = std::move(s);
        descs[i].data = (const uint8_t*)backing[i].data();
    } else {
        descs[i].data = nullptr; // allowed when n==0
    }
}

// Commitments buffer: must be non-NULL if num_sequences>0. We keep a stable pointer for output.
std::vector<struct sxt_ristretto255_compressed> commits_vec(num_sequences ? num_sequences : 1);
struct sxt_ristretto255_compressed* commitments = commits_vec.data();

// Offset for internal generators.
uint64_t offset_generators = (uint64_t)(*FUZZ_PARAM(unsigned int) % 256);

// Invoke target function.
sxt_curve25519_compute_pedersen_commitments(commitments, num_sequences, descs.data(), offset_generators);

// Provide one commitment object back to the pool.
struct sxt_ristretto255_compressed* commitment = commitments;
